    // Password Preset: 1 - 2 - 3
    localparam PASS_1 = 4'd1;
    localparam PASS_2 = 4'd2;
    localparam PASS_3 = 4'd3;

    reg [2:0] state;

    assign state_out = state;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state         <= S_INIT;
            unlocked      <= 1'b0;
            alarm         <= 1'b0;
            attempts_left <= 2'd3;
        end else if (enter_btn) begin
            case (state)
                S_INIT: begin
                    if (key_code == PASS_1) begin
                        state <= S_DIGIT1;
                    end else begin
                        if (attempts_left > 2'd1) begin
                            attempts_left <= attempts_left - 1'b1;
                            state <= S_INIT;
                        end else begin
                            attempts_left <= 2'd0;
                            state <= S_ALARM;
                            alarm <= 1'b1;
                        end
                    end
                end

                S_DIGIT1: begin
                    if (key_code == PASS_2) begin
                        state <= S_DIGIT2;
                    end else begin
                        if (attempts_left > 2'd1) begin
                            attempts_left <= attempts_left - 1'b1;
                            state <= S_INIT;
                        end else begin
                            attempts_left <= 2'd0;
                            state <= S_ALARM;
                            alarm <= 1'b1;
                        end
                    end
                end

                S_DIGIT2: begin
                    if (key_code == PASS_3) begin
                        state    <= S_PASS;
                        unlocked <= 1'b1;
                        alarm    <= 1'b0;
                    end else begin
                        if (attempts_left > 2'd1) begin
                            attempts_left <= attempts_left - 1'b1;
                            state <= S_INIT;
                        end else begin
                            attempts_left <= 2'd0;
                            state <= S_ALARM;
                            alarm <= 1'b1;
                        end
                    end
                end

                S_PASS: begin
                    unlocked <= 1'b1;
                end

                S_ALARM: begin
                    state         <= S_ALARM;
                    alarm         <= 1'b1;
                    attempts_left <= 2'd0;
                end

                default: state <= S_INIT;
            endcase
